import sys

def is_palindrome_brute(x: int) -> bool:
    s = str(x)
    return s == s[::-1]

if __name__ == '__main__':
    data = sys.stdin.read().strip().split()
    if not data:
        sys.exit(0)
    x = int(data[0])
    print('true' if is_palindrome_brute(x) else 'false')

import sys

def is_palindrome_opt(x: int) -> bool:
    if x < 0 or (x % 10 == 0 and x != 0):
        return False
    orig, rev = x, 0
    while x > 0:
        rev = rev * 10 + x % 10
        x //= 10
    return orig == rev

if __name__ == '__main__':
    data = sys.stdin.read().strip().split()
    if not data:
        sys.exit(0)
    x = int(data[0])
    print('true' if is_palindrome_opt(x) else 'false')

import sys

def is_palindrome_best(x: int) -> bool:
    if x < 0 or (x % 10 == 0 and x != 0):
        return False
    rev = 0
    while x > rev:
        rev = rev * 10 + x % 10
        x //= 10
    # 偶数位：x == rev；奇数位：x == rev // 10
    return x == rev or x == rev // 10

if __name__ == '__main__':
    data = sys.stdin.read().strip().split()
    if not data:
        sys.exit(0)
    x = int(data[0])
    print('true' if is_palindrome_best(x) else 'false')
